<?php /** @var array $sales, $tot, $f, $bars, $staff, $days, $done; string $btab, $bbase */ $done = $done ?? []; echo view('pro/bars/_nav', compact('btab', 'bbase')); ?>
<form class="filters card"><select name="kind"><option value="">Ventes, recharges, remboursements</option><?php foreach (['sale' => 'Ventes', 'topup' => 'Recharges cashless', 'cashout' => 'Remboursements de solde'] as $k => $l): ?><option value="<?= $k ?>" <?= ($f['kind'] ?? '') === $k ? 'selected' : '' ?>><?= $l ?></option><?php endforeach; ?></select><select name="bar"><option value="">Tous les bars</option><?php foreach ($bars as $b): ?><option value="<?= (int)$b['id'] ?>" <?= $f['bar'] === (int)$b['id'] ? 'selected' : '' ?>><?= e($b['name']) ?></option><?php endforeach; ?></select>
  <select name="method"><option value="">Tous les paiements</option><?php foreach (Till::METHODS as $k => $l): ?><option value="<?= $k ?>" <?= $f['method'] === $k ? 'selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select>
  <select name="staff"><option value="">Tous les serveurs</option><?php foreach ($staff as $s): ?><option value="<?= (int)$s['id'] ?>" <?= $f['staff'] === (int)$s['id'] ? 'selected' : '' ?>><?= e($s['name']) ?></option><?php endforeach; ?></select>
  <select name="day"><option value="">Tous les jours</option><?php foreach ($days as $d): ?><option value="<?= e($d) ?>" <?= $f['day'] === $d ? 'selected' : '' ?>><?= e(fr_date($d, false)) ?></option><?php endforeach; ?></select>
  <input name="q" value="<?= e($f['q']) ?>" placeholder="N° de ticket ou produit"><label class="check"><input type="checkbox" name="undone" value="1" <?= $f['undone'] ? 'checked' : '' ?>> <span>Avec les annulées</span></label><button class="btn btn-sm">Filtrer</button>
  <a class="btn btn-sm btn-light" href="<?= url($bbase . '/ventes', array_filter($f) + ['export' => 'csv']) ?>">CSV</a></form>
<div class="page-head-row mt"><div class="kpi-mini"><span>Ventes</span><b><?= (int)$tot['n'] ?></b></div><div class="kpi-mini"><span>Encaissé</span><b><?= e(money((int)$tot['t'])) ?></b></div><div class="kpi-mini"><span>Offert</span><b><?= e(money((int)$tot['o'])) ?></b></div><div class="kpi-mini"><span>Remises</span><b><?= e(money((int)$tot['d'])) ?></b></div><div class="kpi-mini"><span>Recharges</span><b><?= e(money((int)$tot['top'])) ?></b><small class="muted">remboursé <?= e(money((int)$tot['cashout'])) ?></small></div></div>
<div class="card table-card"><div class="table-wrap"><table class="table table-sm"><thead><tr><th>Ticket</th><th>Bar · serveur</th><th>Articles</th><th>Paiement</th><th class="num">Montant</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>
  <?php foreach ($sales as $s): $items = json_decode((string)$s['items'], true) ?: []; ?><tr class="<?= $s['undone'] ? 'muted' : '' ?>"><td><a href="<?= url('/recu/' . $s['receipt_token']) ?>" target="_blank">n° <?= (int)$s['ticket_no'] ?></a><br><small class="muted"><?= e(date('d/m H:i', strtotime($s['created_at']))) ?><?= $s['offline'] ? ' · hors ligne' : '' ?></small></td>
    <td><?= e($s['bar']) ?><br><small class="muted"><?= e((string)($s['staff_name'] ?: $s['staff'])) ?></small></td>
    <td><small><?= e(implode(', ', array_map(fn($l) => $l['qty'] . ' × ' . $l['name'] . (!empty($l['offered']) ? ' (offert)' : ''), $items))) ?></small><?= $s['offer_reason'] ? '<br><small class="muted">' . e($s['offer_reason']) . ($s['approver'] ? ' · validé par ' . e($s['approver']) : '') . '</small>' : '' ?></td>
    <td><?= ($s['kind'] ?? 'sale') !== 'sale' ? '<span class="badge grey">' . (($s['kind'] === 'topup') ? 'Recharge' : 'Remboursement') . '</span> ' : '' ?><?= $s['payments_json'] ? '<small class="muted">' . e(implode(' + ', array_map(fn($pt) => (Till::METHODS[$pt['method']] ?? $pt['method']) . ' ' . money((int)$pt['amount']), json_decode((string)$s['payments_json'], true) ?: []))) . '</small><br>' : '' ?><span class="badge <?= ['cashless' => 'violet', 'card' => 'blue', 'cash' => 'green', 'allowance' => 'orange', 'offered' => 'orange', 'split' => 'grey'][$s['method']] ?? 'grey' ?>"><?= e(Till::METHODS[$s['method']] ?? $s['method']) ?></span><?= $s['undone'] ? ' <span class="badge grey">annulée</span>' : '' ?><?= $s['receipt_sent_at'] ? '<br><small class="muted">ticket envoyé</small>' : '' ?></td>
    <td class="num"><b><?= e(money((int)$s['amount'])) ?></b><?= (int)$s['offered_value'] ? '<br><small class="muted">offert ' . e(money((int)$s['offered_value'])) . '</small>' : '' ?><?= (int)$s['discount'] ? '<br><small class="muted">remise ' . e(money((int)$s['discount'])) . '</small>' : '' ?></td>
    <td class="nowrap"><?php $k = $s['kind'] ?? 'sale'; $left = []; foreach ($items as $i => $l) if (($l['kind'] ?? '') === 'product' && (int)$l['qty'] > 0) { $r = (int)$l['qty'] - (int)($done[(int)$s['id']][$i] ?? 0); if ($r > 0) $left[$i] = [$l, $r]; }
      if ($s['undone']): ?><span class="badge grey">Annulée</span><?php elseif (($k === 'sale' && $left) || $k === 'topup'): ?>
      <details class="menu cancel-menu"><summary class="btn btn-sm btn-light">Annuler</summary><div class="menu-list" style="min-width:300px;padding:12px">
        <form method="post" class="stack"><?= csrf_field() ?><input type="hidden" name="action" value="cancel_sale"><input type="hidden" name="sale_id" value="<?= (int)$s['id'] ?>">
          <?php if ($k === 'sale' && count($left) > 1): ?>
            <label class="check"><input type="radio" name="scope" value="all" checked> <span>Tout le ticket</span></label>
            <label class="check"><input type="radio" name="scope" value="lines"> <span>Seulement :</span></label>
            <?php foreach ($left as $i => [$l, $r]): ?><div class="row" style="gap:8px;align-items:center"><input type="number" name="q[<?= (int)$i ?>]" min="0" max="<?= $r ?>" value="0" style="width:70px" aria-label="Quantité à annuler : <?= e($l['name']) ?>"><small><?= e($l['name']) ?> (<?= $r ?> max)</small></div><?php endforeach; ?>
          <?php else: ?><input type="hidden" name="scope" value="all"><?php endif; ?>
          <div class="field mb0"><label>Motif</label><input name="reason" required maxlength="90" placeholder="Erreur de saisie, produit manquant…"></div>
          <small class="muted"><?= $k === 'topup' ? 'Le montant est retiré du porte-monnaie (s\'il n\'a pas été dépensé) et doit être rendu au client.' : ['cashless' => 'Le montant est recrédité sur le porte-monnaie.', 'card' => 'À rembourser ensuite sur le terminal de paiement.', 'cash' => 'À rendre en espèces.', 'split' => 'Rendu en espèces.'][$s['method']] ?? 'Le stock est remis.' ?></small>
          <button class="btn btn-sm" data-confirm="Annuler cette <?= $k === 'topup' ? 'recharge' : 'vente' ?> ?">Confirmer l'annulation</button>
        </form></div></details>
      <?php endif; ?></td></tr><?php endforeach; ?>
  <?php if (!$sales): ?><tr><td colspan="6" class="empty">Aucune vente.</td></tr><?php endif; ?>
</tbody></table></div></div>
